const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"Personal protective equipment (PPE)",subtitle:"Personal protective equipment",summary:"Knowing your personal protective equipment and how to use it correctly",blocks:[{body:"Personal protective equipment (PPE) is the last line of defense against injury: before relying on it, hazards must be eliminated or reduced through engineering controls and safe work procedures (Hierarchy of Controls). In factories, wearing PPE is not optional; it is mandatory."},{heading:"1. Main types of PPE",body:"Each part of the body has its own specific equipment:",points:["Head: hard hat — protects against falling objects and impacts.","Eyes: safety glasses — protect against dust, chemicals and flying particles.","Ears: hearing protection (earmuffs or earplugs) — against loud machine noise (85 dB(A) and above).","Hands: gloves — against cuts, heat and chemicals.","Feet: steel-toe safety boots — against crushing and heavy falling objects.","Body: high-visibility (hi-vis) clothing in bright colors — so drivers and other workers can see you."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"PPE",description:"The correct way to put it on"}],quiz:[{question:"According to European standards, when does wearing hearing protection become mandatory?",options:[{text:"50 dB",correct:!1},{text:"70 dB",correct:!1},{text:"85 dB(A) and above (averaged over an 8-hour workday)",correct:!0},{text:"120 dB",correct:!1}],explanation:"Under European Directive 2003/10/EC, when the average noise level over an 8-hour workday reaches 85 dB(A), hearing protection must be worn. OSHA also requires a hearing conservation program at 85 dBA."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"Machine safety",subtitle:"Machine safety and guarding",summary:"Protecting workers from the moving parts of machinery",blocks:[{body:"Industrial machines are extremely powerful and can cause serious injuries or the loss of a limb in a split second."},{heading:"1. Machine guards",body:"These safeguards must be fitted on all hazardous machines:",points:["Fixed guards: to enclose moving belts and gears.","Emergency stop button (E-Stop): must be within the operator's reach and colored red on a yellow background.","Safety stop sensors: the machine stops if a hand or body comes close to the danger zone."]},{heading:"2. Golden rules",body:"Before and during work:",points:["Never remove a machine guard while the machine is running.","Do not wear loose clothing, chains or rings, and tie back long hair, so nothing gets caught in the machine.","If a machine malfunctions, stop it immediately with the E-Stop button, and never put your hand inside the machine without applying the LOTO procedure."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"Machine guards",description:"An example of a correct guard"}],quiz:[{question:"Is it acceptable to remove a machine guard while the machine is running?",options:[{text:"Yes, if necessary",correct:!1},{text:"No, it is never acceptable",correct:!0},{text:"Only for cleaning",correct:!1},{text:"All of the answers are correct",correct:!1}],explanation:"Removing a machine guard while the machine is running is one of the most dangerous behaviors. Cleaning and repairs are carried out only after the machine has been stopped and locked out (LOTO)."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"Electrical safety",subtitle:"Industrial electrical safety (LOTO)",summary:"Electrical hazards and the lockout/tagout (LOTO) system",blocks:[{body:"Electricity in factories runs at high voltage; an electric shock can cause death or severe burns."},{heading:"1. Lockout/tagout system (LOTO)",body:"This is the most important procedure before repairing or cleaning machinery:",points:["Lockout: isolate the main power source and apply your personal lock to it.",'Tagout: attach a tag that reads "Work in progress — do not switch on", with your name and the date.',"The key stays only with the person doing the repair; before starting, verify that the machine is truly de-energized."]},{heading:"2. Cable inspection",body:"Always check:",points:["Do not use cut cables or cables with exposed wires.","Electricity and water do not mix; do not use electrical equipment in wet areas."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"LOTO",description:"How do we use the lock?"}],quiz:[{question:"What is the purpose of LOTO?",options:[{text:"Cleaning",correct:!1},{text:"Isolating and locking out energy before repairs",correct:!0},{text:"Increasing machine speed",correct:!1},{text:"None of these",correct:!1,fixed:!0}],explanation:"The LOTO system is used so that no one can switch the power back on while a worker is working on the machine (OSHA 29 CFR 1910.147)."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"Fire extinguishers — complete training",subtitle:"Fire extinguisher — complete training (PASS)",summary:"A detailed look at extinguisher types, fire classes and the PASS technique",blocks:[{body:"A fire extinguisher is a key piece of equipment for putting out small fires in their early stage. In a factory, every employee must know how to use an extinguisher quickly and correctly. Knowing the types of extinguishers and the classes of fire will protect your life and the lives of your coworkers. A portable extinguisher discharges for only a few seconds, so it must be aimed correctly. If the fire grows or the smoke becomes heavy, leave the extinguisher, get out and call 115."},{heading:"1. Fire classes under NFPA",body:"Under the American system (NFPA), fires are divided into 5 classes, and each class requires a suitable extinguisher. Classes here use NFPA 10 letters as the project reference; the official system for Duhok is not yet confirmed. EN 2 equivalents: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F.",points:["Class A (ordinary solids): wood, paper, fabric, plastic. Extinguisher: water, foam, ABC powder.","Class B (flammable liquids and gases): gasoline, kerosene, oil, alcohol, gas. Liquids: CO₂, ABC powder or foam; for alcohol and other polar solvents, CO₂, dry chemical or alcohol-resistant (AR) foam, because ordinary foam breaks down on them. Gas: stop the gas first if it is safe; never put out a gas flame you cannot stop. (Never use water!)","Class C (energized electrical equipment): switches, transformers, electrical panels, generators. Extinguisher: CO₂, ABC powder, clean agent. (Do not use water or foam unless the label shows a Class C rating or an electrical-test marking, as on some water-mist units!)","Class D (metals): combustible metals — magnesium, titanium, sodium and aluminum powder. Extinguisher: only a Class D extinguisher or agent whose label lists that metal; the agent differs from metal to metal. (Water can cause an explosion!)","Class K (kitchen): cooking oils and fats. Extinguisher: wet chemical. (Water spreads burning oil!) — under EN 2 this is Class F."]},{heading:"2. Types of extinguishers in factories",body:"Color is not the fire class. Under BS EN 3 the extinguisher body is red; in the UK a colored band (BS 7863) shows the agent. Other countries use other colors and the color practice in Duhok is not yet confirmed, so always read the label and its class symbols. Classes below are in NFPA letters:",points:["Water extinguisher: all red, no band — for Class A only (wood, paper). Never use it on electrical equipment or oil!","CO₂ extinguisher: black band in the UK — for Class B and live electrical equipment (NFPA B and C; under EN 2, C means gas and CO₂ is not rated for gas fires). It releases a very cold gas and the horn becomes extremely cold; hold only the handle, never the horn, or you will get a cold burn! CO₂ has a short range and is not for deep-seated wood or paper fires: start from the distance on its label and move closer only as the fire gets smaller. In small rooms, leave and ventilate after use, because CO₂ reduces the oxygen level.","ABC dry powder extinguisher: blue band in the UK — for Classes A, B and C (not D or K). It is the most common type. It discharges a white powder; drawbacks: it reduces visibility and contaminates equipment.","Foam extinguisher (AFFF): cream band in the UK — for Classes A and B. It spreads a foam blanket over the liquid and cuts off the oxygen. Do not use it on electrical equipment!","Clean agent extinguisher: its rating depends on the model, so read the label (often B and C in NFPA letters; some models also A) — for sensitive equipment and server rooms. It leaves no residue and does not damage electronic equipment.","Special extinguisher (Class D): for combustible metals in factories — its agent must be listed on the label for the metal in use. Never put water on burning metal!"]},{heading:"3. The PASS technique — in detail",body:"Before you use an extinguisher, every answer must be yes: the fire is small and just starting, the extinguisher is the right type, your exit is behind you, the alarm has been raised and 115 called, you are trained and no smoke or heat blocks your way out. If the fire does not go out at once, get out and close the door. PASS is the general method for most hand-held extinguishers; Class D, wet chemical, clean agent and wheeled units: follow the label and the manufacturer's instructions:",points:["P = Pull: pull out the safety pin. This pin prevents the extinguisher from being discharged by accident.","A = Aim: aim the extinguisher nozzle at the base of the fire — not at the flames! The fuel of the fire is at the base.","S = Squeeze: squeeze the extinguisher handles firmly to discharge the agent.","S = Sweep: sweep the nozzle from side to side across the base of the fire until the fire is completely out; then keep watching the area so the fire does not reignite."]},{heading:"4. Monthly extinguisher inspection",body:"Visual check every month, by the person in charge (NFPA 10):",points:["Pressure gauge, if there is one: the needle must be in the green zone. CO₂ extinguishers have no gauge: lift one to feel that it is full.","Safety pin and tamper seal: must be in place and unbroken.","Nozzle: must not be broken or blocked.","Extinguisher body: must not be rusted, cracked or damaged.","Inspection tag and label: the tag shows the date of the last inspection; the label is readable and faces out; the extinguisher is in its place, visible and easy to reach.","Note: keep these separate. Inspection and maintenance once a year by a qualified technician; recharge after any use, even a short one; 6-year maintenance: stored-pressure dry chemical extinguishers that need a 12-year hydrostatic test are emptied and checked inside every 6 years; hydrostatic test (pressure test of the cylinder) every 5 years for water, foam (AFFF), CO₂ and stainless-steel dry chemical extinguishers, and every 12 years for stored-pressure dry chemical extinguishers with mild steel, brazed brass or aluminum shells. A test date is not a replacement date. The rules for Duhok are not yet confirmed."]},{heading:"5. Specific hazards in factories",body:"A factory is a high-risk environment for these reasons:",points:["Chemicals: solvents, alcohol, thinner — all of them are Class B.","High-voltage electricity: electrical panels and transformers — Class C (NFPA).","Wood dust and flour dust: in some factories these can cause a dust explosion.","Welding and cutting: welding sparks can start Class A and Class B fires.","Fuel storage: must be in a dedicated room or outside the building, with a suitable extinguisher (foam or powder) nearby.","Placement: mount extinguishers near doors and walkways; the travel distance to a Class A extinguisher must not exceed 23 meters (75 feet), and for liquids 9-15 meters (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"Fire extinguishers in factories",description:"The PASS technique and extinguisher types on video"}],quiz:[{question:"In NFPA letters, which fire classes is a CO₂ extinguisher rated for?",options:[{text:"A and D",correct:!1},{text:"B and C",correct:!0},{text:"A and K",correct:!1},{text:"D and K",correct:!1}],explanation:"CO₂ is suitable for flammable liquids (B) and electrical equipment (C), because it leaves no residue and does not conduct electricity. Under EN 2, C means gas fires, and CO₂ is not rated for them."},{question:"In the PASS technique, where should the extinguisher nozzle be aimed?",options:[{text:"At the flames",correct:!1},{text:"At the base of the fire",correct:!0},{text:"Away from the fire",correct:!1},{text:"At the ceiling",correct:!1}],explanation:"Always aim the nozzle at the base of the fire, because that is where the fuel is."},{question:"Why must water never be poured on a cooking-oil fire (Class K)?",options:[{text:"It has no effect",correct:!1},{text:"Water spreads the burning oil and creates a large flare-up",correct:!0},{text:"The oil absorbs the water",correct:!1},{text:"The water itself burns",correct:!1}],explanation:"Water on hot oil boils instantly and throws the burning oil into the air, creating a large fireball. Use a wet chemical extinguisher or a lid, and turn off the heat."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"First aid and CPR",subtitle:"First aid and CPR — complete training",summary:"Complete training in first aid, CPR and emergency response in factories",blocks:[{body:"First aid is the initial help given to an injured or sick person before medical teams arrive. In factories the risk of injury is very high — from cuts and burns to electric shock and falls from height. Every employee must know how to call the ambulance (122), perform CPR, stop bleeding and protect the casualty until the ambulance arrives. This lesson follows the AHA 2025 guidelines and Stop the Bleed."},{heading:"1. Cardiopulmonary resuscitation (CPR) — in detail",body:"CPR is a life-saving procedure used when a person's heart stops and normal breathing is absent. Follow these steps:",points:["1. Scene safety: before anything else, make sure the area is safe (no live electricity, fire or gas), so you do not become a second casualty.",'2. Responsiveness: tap the casualty firmly on the shoulders and ask loudly: "Are you okay? Can you hear me?"',"3. Call: if there is no response and the person is not breathing or is only gasping, call 122 immediately (or have someone else call) and ask for an AED to be brought.","4. Chest compressions: place the heel of one hand on the center of the chest (the lower half of the breastbone) and the other hand on top. Give 30 hard, fast compressions: depth 5-6 cm, rate 100-120 compressions per minute and let the chest recoil fully.","5. Rescue breaths: tilt the head back and lift the chin, pinch the nose and give 2 breaths (each about 1 second, until the chest rises). If you cannot or are unwilling to give breaths, continue chest compressions only.","6. Continue (30:2): keep repeating 30 compressions and 2 breaths until the ambulance arrives, an AED is ready or the casualty starts breathing normally.","7. Using the AED: as soon as it arrives, switch it on, attach the pads to the bare chest and follow the device's voice prompts; do not touch the casualty while a shock is delivered."]},{heading:"2. Bleeding control (Stop the Bleed)",body:"Severe bleeding can kill a person within a short time, so call 122 and take these steps quickly:",points:["Direct pressure: place a clean cloth on the wound and press hard with both hands. If the cloth becomes soaked with blood, do not remove it; place another one on top and keep pressing.","Wound packing: if the wound is deep (for example in the thigh, armpit or neck), pack clean cloth or hemostatic gauze into the wound and press hard. Do not elevate the injured limb and do not look for pressure points.","Tourniquet: if bleeding from an arm or leg is life-threatening, apply a tourniquet early, 5-7 cm above the wound (toward the body), tighten it firmly, write down the time and never loosen it.","Embedded object: if a piece of metal or glass is embedded in the wound, never pull it out! That would increase the bleeding. Apply pressure around it and stabilize it."]},{heading:"3. Treating burns",body:"Burns in factories are dangerous; treat them as follows, and call 122 for large burns or burns to the face or hands:",points:["Thermal burns: immediately cool the burn under cool running water (not ice water) for 20 minutes. Quickly remove rings and watches before the area swells.","Chemical burns: remove contaminated clothing and flush the skin with plenty of running water for 20 minutes or longer, and check the substance's SDS.","Electrical burns: first, cut off the power! Then cool the burn as you would a thermal burn and call 122, because electricity can cause damage to the heart and inside the body.","Caution: do not burst burn blisters, and do not use ice, butter or grease, toothpaste or ointments without medical advice."]},{heading:"4. Fractures and spinal injuries",body:"After a fall from height or when a fracture is suspected:",points:["Splinting: if a fracture is suspected, do not move the injured limb. Immobilize it in the position found with a piece of wood or cardboard to reduce pain.","Protecting the back and neck: if someone has fallen from height, do not move them unless the location is dangerous (for example, fire), because moving them can cause paralysis. Keep the head still and call 122.","Cooling: to reduce swelling, wrap ice in a piece of cloth and place it on the painful area for 20 minutes; do not put ice directly on the skin."]},{heading:"5. Electric shock and rescue",body:"Electricity can stop the heart; follow these procedures:",points:["Cut off the power immediately: do not touch the casualty until the power has been cut off, because the current will pass through you too.","Safe separation: if you cannot cut off the power and the voltage is low, use a dry piece of wood or plastic to move the wire away from the casualty while standing on something dry. Do not go near high-voltage lines; call 115.","Medical check: everyone who has received an electric shock, even if they feel fine, must go to the hospital for a heart check; call 122."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"CPR and first aid",description:"CPR training and helping injured workers in factories"}],quiz:[{question:"In CPR, what should the chest compression rate be per minute?",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150+",correct:!1}],explanation:"According to AHA 2025, the compression rate is 100-120 compressions per minute, at a depth of 5-6 cm for adults, so that blood reaches the brain."},{question:"If a sharp object is embedded in a wound, what will you do?",options:[{text:"I pull it out",correct:!1},{text:"I leave it in place and call 122",correct:!0},{text:"I keep my hands away from it and do nothing",correct:!1},{text:"I wash it with water",correct:!1}],explanation:"Pulling the object out will increase the bleeding. It must stay in place and be stabilized until a doctor removes it at the hospital."},{question:"If someone has received an electric shock, what is the first thing you do?",options:[{text:"I grab their hand",correct:!1},{text:"I start CPR",correct:!1},{text:"I cut off the power",correct:!0},{text:"I pour water on them",correct:!1}],explanation:"The power source must be cut off first so the current does not pass through you too; then call 122 and start CPR if needed."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"Chemicals (SDS)",subtitle:"Chemical safety and labeling",summary:"Handling chemicals and recognizing their hazards",blocks:[{body:"Chemicals in factories can cause skin burns, poisoning, fires or explosions."},{heading:"1. What is an SDS?",body:"The Safety Data Sheet (SDS) gives the information for each substance in 16 sections, including:",points:["The composition of the substance and its hazards.","Which PPE is required (respirator, gloves, eye protection).","First aid if the substance contacts the body, and firefighting measures."]},{heading:"2. GHS pictograms",body:"Some of the symbols found on containers and packaging:",points:["Flame: flammable substance.","Skull and crossbones: acutely toxic, potentially fatal substance.","Corrosion: an acidic or alkaline substance that eats away skin and metals."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"SDS",description:"GHS hazard pictograms"}],quiz:[{question:"Where can we find out which respirator is required for a chemical?",options:[{text:"On the signs on the wall",correct:!1},{text:"In the SDS",correct:!0},{text:"Ask a coworker",correct:!1},{text:"No respirator is needed",correct:!1}],explanation:"The SDS provides all the protection information specific to that substance, including the type of PPE required (Section 8)."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"Working at height",subtitle:"Fall protection and ladders",summary:"Preventing falls from scaffolding, roofs and ladders",blocks:[{body:"Falls from height are one of the leading causes of death in factories and on construction sites."},{heading:"1. Fall protection",body:"Any work at height (OSHA: from 1.2 meters in general industry and from 1.8 meters in construction) requires the following:",points:["Full-body harness: worn correctly and fastened securely.","Lanyard: must be attached to a secure anchor point.","Guardrails: around scaffolding, roofs and open edges."]},{heading:"2. Ladder safety",body:"The 3-point contact rule:",points:["You must always have 3 limbs (two feet and one hand, or two hands and one foot) in contact with the ladder.","The ladder angle must be 4:1 (for every 4 meters of height, the base of the ladder is 1 meter away from the wall)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"Working at height",description:"Using a harness"}],quiz:[{question:"What does the 3-point rule on a ladder mean?",options:[{text:"3 people on it at the same time",correct:!1},{text:"Stay on it for 3 minutes",correct:!1},{text:"Always keep 3 limbs in contact with the ladder",correct:!0},{text:"Tie the ladder with 3 ropes",correct:!1}],explanation:"The 3-point rule ensures that the worker keeps their balance and does not fall."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"Confined spaces",subtitle:"Confined space safety",summary:"Working inside tanks, pipes and manholes",blocks:[{body:"Confined spaces are dangerous because the air inside is not refreshed, oxygen levels can drop and deadly gases can build up."},{heading:"1. Main hazards",body:"Before you enter, be aware of:",points:["Oxygen deficiency (below 19.5%): causes asphyxiation.","Toxic gases such as CO (odorless) and H₂S (which knocks out the sense of smell at high concentrations).","Risk of fire and explosion if flammable gases or vapors are present."]},{heading:"2. Entry procedures",body:"These conditions must be in place:",points:["Air testing with a gas monitor before entry and during the work.","An attendant who stays outside, keeps watch on the entrant inside and never enters under any circumstances.","An entry permit, means of communication and a rescue plan must be in place."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"Confined spaces",description:"Air testing"}],quiz:[{question:"Is it acceptable for the attendant outside to enter without equipment to rescue a coworker?",options:[{text:"Yes, out of humanity",correct:!1},{text:"No, because they will be overcome too",correct:!0},{text:"Yes, if they hold their breath",correct:!1},{text:"None of these",correct:!1,fixed:!0}],explanation:"According to NIOSH studies, a large share of confined-space deaths are people who entered without equipment or training to attempt a rescue. The attendant must call the rescue team and 115."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"Noise and hearing protection",subtitle:"Hearing conservation",summary:"Protection against the noise of heavy machinery",blocks:[{body:"Deafness or hearing loss caused by factory noise develops gradually and cannot be cured."},{heading:"1. Noise levels",body:"When does noise become a hazard?",points:["85 dB(A): the threshold at which the hazard begins, for an 8-hour workday.","100 dB(A): safe without protection for only 15 minutes a day (NIOSH).","Warning sign: if you notice ringing in your ears (tinnitus) after work, the noise was too loud."]},{heading:"2. Protective equipment",body:"Hearing protection devices (HPD):",points:["Earplugs: give good protection when inserted correctly.","Earmuffs: easy to put on and suitable for loud noise.","Wear both together in very noisy areas."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"Noise",description:"How do you use hearing protection?"}],quiz:[{question:"If the noise level reaches 100 dB(A), how long can you stay without hearing protection according to NIOSH?",options:[{text:"1 hour",correct:!1},{text:"15 minutes",correct:!0},{text:"4 hours",correct:!1},{text:"All day",correct:!1}],explanation:"According to NIOSH, every 3 dB increase halves the safe exposure time: 85 dB(A) for 8 hours, and 100 dB(A) for only 15 minutes."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"Manual handling (ergonomics)",subtitle:"Safe lifting techniques",summary:"Preventing back and muscle injuries",blocks:[{body:"Back injuries are among the most common injuries in factories, caused by lifting loads incorrectly."},{heading:"1. The correct lifting technique",body:"Following these steps protects your back:",points:["Bend your knees: use the strength of your legs, not your back.","Keep the load close to your body: the farther the load is from you, the greater the strain on your back.","Keep your back straight: do not bend your back while lifting something heavy.","Do not twist your body: if you need to move the load to one side, turn your whole body using your feet."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"Lifting a load",description:"The correct technique"}],quiz:[{question:"When lifting something heavy, where should the effort come from?",options:[{text:"The back",correct:!1},{text:"The leg muscles",correct:!0},{text:"The shoulders",correct:!1},{text:"The hands only",correct:!1}],explanation:"The leg muscles are stronger and protect the back from injury."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"Gases and ventilation",subtitle:"Ventilation and toxic gases",summary:"Controlling air quality and toxic gases",blocks:[{body:"Proper ventilation in a factory is important to prevent the buildup of dust and gases that cause respiratory diseases."},{heading:"1. Carbon monoxide (CO)",body:"The silent killer gas:",points:["It is colorless and odorless.","It is produced by burning fuel and by gasoline and diesel engines (such as generators and forklifts).","Symptoms: headache, dizziness, nausea and loss of consciousness. If you notice these symptoms, get outside immediately and call 122."]},{heading:"2. Types of ventilation",body:"How is the air exchanged?",points:["Natural ventilation: open doors and windows.","Mechanical ventilation: fans and local exhaust ventilation (LEV) systems.","Personal protection: filter respirators as specified in the SDS; however, filter respirators do not protect against CO or oxygen deficiency."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"Gas",description:"Carbon monoxide (CO)"}],quiz:[{question:"Why is CO dangerous?",options:[{text:"Because it smells bad",correct:!1},{text:"Because it cannot be seen or smelled",correct:!0},{text:"Because it is red",correct:!1},{text:"Because it is only produced at night",correct:!1}],explanation:"Because it cannot be sensed, workers are poisoned without realizing it. Install CO detectors wherever engines are running."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"Emergency evacuation",subtitle:"Emergency assembly points",summary:"The plan for getting out during a fire or disaster",blocks:[{body:"Knowing your exit route can make the difference between life and death."},{heading:"1. Evacuation rules",body:"When the alarm sounds:",points:["Walk calmly and quickly, do not run and do not use the elevator.","Close doors behind you so fire and smoke do not spread, but do not lock them.","Go to the assembly point so that employees can be counted.","Never go back inside until the safety officer or the 115 teams give permission."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"Evacuation drill",description:"Evacuation training"}],quiz:[{question:"When the alarm sounds, what will you do?",options:[{text:"Gather my belongings",correct:!1},{text:"Walk calmly toward the exit",correct:!0},{text:"Hide under a desk",correct:!1},{text:"Shout",correct:!1}],explanation:"Evacuating calmly and quickly is the best way to protect life."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"Welding safety",subtitle:"Welding and cutting hazards",summary:"Protection from welding radiation, heat and fumes",blocks:[{body:"Welding work involves the risk of ultraviolet (UV) radiation, severe burns, and toxic gases and fumes."},{heading:"1. Eye and skin protection",body:"What welders need:",points:["A welding helmet with the correct filter shade: to protect the eyes from UV radiation and the intense light of the welding arc.","Long leather gauntlets: for protection from heat and spatter.","A leather apron: to protect the body."]},{heading:"2. Fire hazard (hot work)",body:"Before starting, obtain a hot-work permit and:",points:["Clear combustible materials from around the work area (NFPA 51B: within 11 meters / 35 feet), or cover them with fire-resistant blankets.","Have a suitable fire extinguisher ready close by.","Fire watch: stays at the location during the work and for at least 1 hour after the work is finished; the area is then monitored for up to 3 more hours, as decided by the permit authorizing individual (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"Welding",description:"Wearing protective gear correctly"}],quiz:[{question:"Why does the fire watch stay at the location for at least 1 hour after welding?",options:[{text:"For cleaning",correct:!1},{text:"To prevent a hidden fire from developing",correct:!0},{text:"To cool down the metal",correct:!1},{text:"It is not necessary",correct:!1}],explanation:"Sparks often fall into cracks and materials and start a fire some time later. Under NFPA 51B (2019 edition onward), the fire watch continues for at least 1 hour after the work."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"Material handling equipment",subtitle:"Forklift and vehicle safety",summary:"Forklift safety and driving inside the factory",blocks:[{body:"A forklift is a heavy machine with a risk of crushing and tip-over if it is not operated correctly."},{heading:"1. Operating rules",body:"For forklift operators:",points:["Only trained and authorized persons may operate a forklift (OSHA 1910.178).","Never carry anyone on the forks of a forklift or beside you.","Do not exceed the rated capacity of the machine, so it does not tip over, and fasten your seat belt.","Slow down and sound the horn at every corner and doorway."]},{heading:"2. Pedestrian safety",body:"If you are walking near a forklift:",points:["Make eye contact with the operator and keep a safe distance.","Walk in the marked pedestrian walkways."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"Forklift",description:"Recognizing blind spots"}],quiz:[{question:"If a forklift operator is carrying a tall load and cannot see ahead, what should they do?",options:[{text:"Drive fast",correct:!1},{text:"Drive in reverse",correct:!0},{text:"Sound the horn and close their eyes",correct:!1},{text:"None of these",correct:!1,fixed:!0}],explanation:"When the load blocks the operator's view, they must drive in reverse so they can see where they are going (OSHA 1910.178)."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"Safety signs",subtitle:"Safety signs and symbols",summary:"Understanding safety colors and symbols (ISO 7010)",blocks:[{body:"Safety signs warn us about hazards in a universal language."},{heading:"1. The meaning of colors (ISO 7010)",body:"Each color conveys a specific message:",points:["Red: prohibition or firefighting equipment (example: no smoking).","Yellow: warning and danger (example: electrical hazard).","Blue: mandatory (example: hard hat must be worn).","Green: safe condition and exits (example: emergency exit door)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"Safety signs",description:"Standard symbols"}],quiz:[{question:"What does a yellow sign mean?",options:[{text:"Prohibition",correct:!1},{text:"Warning and danger",correct:!0},{text:"Safe place",correct:!1},{text:"Use of water",correct:!1}],explanation:'Yellow always means "be careful" or "there is a hazard".'}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"Housekeeping",subtitle:"Order and maintenance",summary:"Organizing the workplace to reduce hazards",blocks:[{body:"A clean workplace is a safe workplace. Many accidents happen because of slipping and tripping over scattered materials."},{heading:"1. General rules",body:"For all workers:",points:["Clean up spilled oil or water as soon as possible.","Collect waste in designated bins.","Keep walkways and exits open and free of obstructions.","Return every tool to its place when the work is finished."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"Housekeeping",description:"An example of a clean workplace"}],quiz:[{question:"If you see oil spilled on the floor, what will you do?",options:[{text:"Leave it until the cleaner comes",correct:!1},{text:"Clean it up, or put a sign on it and report it",correct:!0},{text:"Jump over it",correct:!1},{text:"Ignore it",correct:!1}],explanation:"Every worker is responsible for keeping their own work area clean and safe, so that no one falls."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"Earthquakes in factories",subtitle:"Earthquake safety in factories",summary:"Worker safety during and after an earthquake",blocks:[{body:"An earthquake creates a double hazard in a factory: the shaking itself, plus falling heavy machinery, chemical spills, broken pipes and gas leaks. Every factory must have an earthquake plan."},{heading:"1. Drop, Cover, Hold On",body:"During an earthquake:",points:["Drop to the ground (Drop) and get under a sturdy table or workbench — away from heavy machinery, shelving and glass.","If there is no table, kneel next to an interior wall and cover your head and neck with your hands (Cover).","Hold on to the table (Hold On) until the shaking stops completely.","Do not run, and do not go under machinery or next to shelving! Heavy machinery and shelving can shift or fall on you."]},{heading:"2. After the earthquake",body:"Once the shaking stops:",points:["Inspect machinery for damage, and do not switch on damaged machinery until it has been inspected.","Check whether any chemicals have spilled, and keep away from them.","If you smell gas — get out quickly, evacuate the factory and call 115 from outside.","Only trained, designated staff shut off the gas, and only if there is a smell of gas or a leaking sound and the gas valve can be reached safely, without entering the area where the gas has collected and without making any spark; shut off the electricity if wiring or electrical panels have been damaged.","Before going back inside, an engineer must inspect the factory building for cracks."]},{heading:"3. Preparedness",body:"Planning ahead:",points:["Prepare an earthquake plan for every department.","Secure heavy machinery with chains or anchor bolts.","Store drums and chemical containers on low, stable shelving.","Keep exit routes open at all times.","Hold a drill once every 6 months."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"Earthquake",description:"An earthquake in a factory"}],quiz:[{question:"During an earthquake in a factory, what is the first thing to do?",options:[{text:"Run outside",correct:!1},{text:"Drop to the ground and get under a sturdy table",correct:!0},{text:"Switch off the machines",correct:!1},{text:"Go near the windows",correct:!1}],explanation:"Drop, Cover, Hold On is the first action inside buildings, away from machinery, shelving and glass."},{question:"After an earthquake in a chemical plant, what is the first thing to check?",options:[{text:"Electricity",correct:!1},{text:"Chemical spills",correct:!0},{text:"Water",correct:!1},{text:"Telephones",correct:!1}],explanation:"Chemical spills are a major hazard after an earthquake and must be checked quickly."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"Floods and water inundation",subtitle:"Flood emergency in industrial areas",summary:"Protecting the factory and its workers during a flood",blocks:[{body:"A flood can completely destroy a factory: it can ruin machinery, spread chemicals and turn the electrical system into a hazard. Factories near rivers and valleys are at greater risk."},{heading:"1. Before the flood",body:"Preparedness:",points:["Follow warnings from the meteorological service.","Move important equipment and chemicals to a higher location.","Prepare the electrical system for automatic shutoff.","Place sandbags in front of the doors and along the foundation of the factory."]},{heading:"2. During the flood",body:"Emergency procedures:",points:["If you can do so safely and the water has not reached the electrical panels, shut off the electricity and gas; never touch anything electrical while standing in water!","Do not enter flood water — 15 cm of fast-moving water can knock a person down, and 30 cm can carry a car away.","Move to higher ground — the second floor or the roof.","Call 115 and stay where you are until the rescue teams arrive."]},{heading:"3. After the flood",body:"Returning and cleaning up:",points:["Do not enter the factory until an engineer confirms that the building is safe.","Do not touch chemicals that have been in contact with flood water — request a hazardous materials (HazMat) team through 115.","Do not switch the power back on until the system has been inspected by a qualified electrician.","Photograph all damage for insurance and reporting."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"Flood",description:"A flood in a factory"}],quiz:[{question:"During a flood in a factory, what is the first thing to do?",options:[{text:"Protect the machinery",correct:!1},{text:"Shut off the electricity and gas, if you can do so safely",correct:!0},{text:"Go home",correct:!1},{text:"Pump out the water",correct:!1}],explanation:"Electricity and gas are the primary hazards during a flood; however, if the water has reached the electrical panels, do not approach them and move to higher ground."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"Civil Defense response in factories",subtitle:"Industrial Civil Defense response and multi-agency coordination",summary:"Organizing the factory response team during incidents and coordinating with 115",blocks:[{body:"Large facilities (oil, gas, chemicals, steel) must have their own emergency response teams that act before the 115 teams arrive. The NFPA 600 standard (Facility Fire Brigades) sets out the organization, training and equipment of facility fire brigades. The first minutes of an incident are critical, so the facility team must be ready and trained."},{heading:"1. Organizing the facility emergency response team (ERT)",body:"Key principles of the emergency response team:",points:["Team size: determined by the facility hazard assessment and the team's assigned duties; NFPA 600 does not set a fixed ratio of members to the number of employees.","Training: based on each member's duties, with refresher training at least once a year.","Incident Commander (IC): only one person gives orders, so that instructions are not mixed up.","Main duties: firefighting, rescue, first aid and building evacuation.","Communications: two-way radio on a dedicated channel, with cell phones as a backup.","Response time: define it in the plan, measure it during drills and improve it.","Recommended: the ICS-100 and ICS-200 courses (FEMA) to learn the Incident Command System."]},{heading:"2. The emergency response plan (ERP)",body:"Requirements for the emergency response plan under the standards:",points:["The emergency action plan must be in writing and available at the workplace; employers with 10 or fewer employees may communicate it orally (OSHA 29 CFR 1910.38).","Main sections: roles, procedures, exit routes, communications, resources, drills and post-incident review.","Assembly points: one primary and one alternate, in a safe location away from the building and from the emergency vehicle access route.","Exit routes: in general, at least 2 exits from every floor (NFPA 101, with some exceptions).","Fire alarm: must be audible or visible in all areas of the building (NFPA 72).","First aid team: every shift must have employees trained in first aid and CPR.","Drills: held regularly, with the results of every drill recorded.","Post-incident review (Post-Response Critique): as soon as possible after every incident."]},{heading:"3. Coordination with Civil Defense (115)",body:"When an incident occurs and the 115 teams arrive, the ERT must take these steps:",points:["1. Call 115 immediately, and 122 if there are casualties.","2. Give the key information: location, type of incident, number of casualties, hazardous materials involved and the access route.","3. Have the site map ready at the gate, showing hazard locations and the electricity and gas shutoff points.","4. Liaison officer: only one person communicates with 115.","5. Have the SDS ready for every chemical on site.","6. Record the names and statements of witnesses.","7. Transfer of command: when 115 arrives, command passes to the 115 commander and the ERT provides support.","8. Documentation: photos, video and the incident log for investigation and insurance."]},{heading:"4. Working with the hazardous materials (HazMat) team",body:"For chemical incidents, a HazMat team is required:",points:["HazMat training levels (OSHA 1910.120 and NFPA 470, which consolidates NFPA 472):","• Awareness level: recognizing the hazard, staying away and raising the alarm — for all employees.","• Operations level: protecting people and the surroundings with defensive actions from a distance.","• Technician level: offensive actions to stop the leak at close range, with specialized PPE.","• Specialist level: in-depth knowledge of specific substances and technical support for technicians.","Three zones: the hot zone, the warm zone and the cold zone.","HazMat PPE levels: A, B, C, D (A gives the highest protection).","Decontamination is carried out in the warm zone, before entering the cold zone.","Untrained employees do not enter the hot zone; they wait for the 115 teams.","The facility plan must state how specialized hazardous materials teams are requested through 115."]},{heading:"5. Multi-agency response",body:"Major incidents require several agencies:",points:["115 Civil Defense: firefighting, rescue and hazardous materials.","122 Ambulance: medical treatment and transport of casualties.","104 Police: cordoning off the area, traffic control and legal investigation.","Security agencies: when explosives or terrorism are suspected — notified through 104.","Ministry of Health: preparing nearby hospitals.","Electricity directorate: cutting off power in the surrounding area.","Water and gas authorities: shutting off water and gas lines.","Environmental authority: if chemicals have been released into the environment.","Emergency Operations Center (EOC): for major incidents involving many agencies."]},{heading:"6. Phases of response (5 phases)",body:"Every incident goes through these 5 phases:",points:["1. Detection: sensors, the fire alarm or a witness.","2. Notification: calling 115, and alerting the ERT and the liaison officer.","3. Response: the ERT acts until the 115 teams arrive.","4. Mitigation: firefighting, rescue and decontamination.","5. Recovery: cleanup, analysis and post-incident review.","Every phase must be documented in an Incident Action Plan (IAP).","The Golden Hour: rapid treatment after a serious injury increases the chance of survival — which is why calling 122 quickly matters."]},{heading:"7. Drills and training",body:"Drills are the foundation of preparedness (recommended schedule):",points:["Tabletop exercise: once every 3 months — a scenario worked through around a table.","Functional drill: once every 6 months — the ERT only, not the whole building.","Full-scale drill: once a year — the entire facility together with 115.","Evaluation: an after-action report as soon as possible.","ERT training: ongoing and based on assigned duties, at least once a year.","Competency standards: NFPA 1081 (Facility Fire Brigade Member), OSHA 1910 Subpart L and ICS-100/200.","Joint drill with 115: once a year for coordination."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"ERT response drill",description:"A full-scale drill at an oil facility"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"Incident Command System (ICS) structure",description:"Incident Command System (ICS) structure"}],quiz:[{question:"How is the size of a facility emergency response team (ERT) determined?",options:[{text:"By a fixed ratio: 1 per 100 employees",correct:!1},{text:"Based on the facility hazard assessment and the team's assigned duties",correct:!0},{text:"By a fixed ratio: 1 per 200 employees",correct:!1},{text:"By a fixed ratio: 1 per 25 employees",correct:!1}],explanation:"NFPA 600 does not set a fixed ratio of members to the number of employees; each facility determines the team size according to its own hazards and duties."},{question:"What does the Golden Hour mean?",options:[{text:"A special working hour",correct:!1},{text:"The initial period after a serious injury, when rapid treatment is critical",correct:!0},{text:"Midday",correct:!1},{text:"The heat of the day",correct:!1}],explanation:"The Golden Hour is the period after a serious injury during which getting the casualty to treatment quickly increases the chance of survival; so call 122 immediately."},{question:"In the ICS, what does the liaison officer do?",options:[{text:"Puts out the fire",correct:!1},{text:"Communicates with outside agencies",correct:!0},{text:"Performs CPR",correct:!1},{text:"Guards the gate",correct:!1}],explanation:"The liaison officer communicates with 115, the police (104), the ambulance service (122) and other agencies."},{question:"What does the HazMat Operations level do?",options:[{text:"Raises the alarm only",correct:!1},{text:"Defensive — preventing the spread from a distance",correct:!0},{text:"Offensive — stopping the leak at close range",correct:!1},{text:"Specialist",correct:!1}],explanation:"The Operations level is defensive: preventing the spread of the substance from a distance, not offensive work at close range."},{question:"What is the hot zone in a HazMat incident?",options:[{text:"A cool, safe place",correct:!1},{text:"A completely clean zone",correct:!1},{text:"The most dangerous zone — HazMat technicians only, with appropriate PPE",correct:!0},{text:"The assembly area",correct:!1}],explanation:"The hot zone is where the hazardous material is; only HazMat technicians in Level A or B PPE enter it."},{question:"When the 115 teams arrive at the incident scene, who takes command?",options:[{text:"The ERT remains in command",correct:!1},{text:"The 115 commander",correct:!0},{text:"The factory manager",correct:!1},{text:"The police",correct:!1}],explanation:"Transfer of command (ICS Transfer): when 115 arrives, command passes to the 115 commander and the ERT provides support."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"Fire classification in factories",subtitle:"Industrial fire classes — NFPA 30/484/654",summary:"Classification specific to industry: flammable liquids, gases, metals and combustible dust",blocks:[{body:"This module uses the NFPA system: A ordinary solids, B flammable liquids and gases, C electrical equipment, D metals, K cooking oil. Classes here use NFPA 10 letters as the project reference; the official system for Duhok is not yet confirmed. EN 2 equivalents: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F. Industry-specific standards: flammable liquids (NFPA 30), combustible metals (NFPA 484) and combustible dust (NFPA 654). Since the 2025 edition, NFPA 484 and NFPA 654 have been consolidated into the NFPA 660 standard."},{heading:"1. Class A — combustible solids in the factory",body:"Common combustible solids in factories:",points:["Fuels: paper, cardboard, fabric, wood, rubber, plastic and pallets.","These materials leave embers and hidden fire behind; after extinguishing, cool the area with water and keep it under watch.","In factories: paper and cardboard storage areas and wooden pallets spread fire quickly.","Extinguisher: water, foam, ABC powder.","Stacks of empty pallets are a major hazard: do not stack them high, and store them outdoors or in a sprinklered area.","Standard: NFPA 13 (sprinkler systems), which also covers storage protection.","Examples in factories: warehouses and packaging lines."]},{heading:"2. Class B — flammable liquids in the factory",body:"One of the most dangerous classes in factories:",points:["Fuels: gasoline, kerosene, diesel, acetone, toluene, xylene.","Flash point: gasoline about -43°C, acetone -20°C, diesel 52°C or higher.","Explosive limits (LEL/UEL): the minimum and maximum vapor concentrations in air that can ignite:","• Gasoline: 1.4-7.6%.","• Acetone: 2.5-12.8%.","• Methanol: 6-36%.","Extinguisher: foam (AFFF or fluorine-free foam), CO₂, ABC powder. For acetone, methanol, alcohols and other polar solvents: CO₂, dry chemical or alcohol-resistant (AR) foam; ordinary foam breaks down on them.","Do not direct a water jet onto a burning liquid — it spreads the fire. A BLEVE (Boiling Liquid Expanding Vapor Explosion) occurs when a pressurized tank is heated by fire.","Liquid classes under NFPA 30 (based on flash point and boiling point):","• Class I (Flammable): flash point below 37.8°C — IA (flash point < 22.8°C and boiling point < 37.8°C), IB (flash point < 22.8°C and boiling point 37.8°C or higher), IC (flash point 22.8 to < 37.8°C).","• Class II (Combustible): flash point 37.8 to < 60°C.","• Class III (Combustible): IIIA from 60 to < 93°C, and IIIB 93°C or higher.","Secondary containment (diking): under NFPA 30, the volume of the containment area must be no less than the liquid that can be released from the largest full tank (100%); a 110% capacity is required by some other regulations and guidelines (to allow for rainwater as well).","Vapor density: gasoline vapor is heavier than air (about 3-4 times) and collects in low-lying areas."]},{heading:"3. Flammable gases — NFPA: Class B, EN 2: Class C",body:"Industrial gases: acetylene, propane, hydrogen:",points:["Sources: acetylene for welding, propane for some forklifts, hydrogen from charging lead-acid batteries.","These substances are gases at normal temperatures and ignite easily. Explosive limits in air: hydrogen 4-75%, propane 2.1-9.5%, acetylene from 2.5% upward. (-253°C is the boiling point of hydrogen, not its flash point.)","The temperature of an oxy-acetylene flame exceeds 3000°C.","Acetylene forms an explosive compound (copper acetylide) with copper; do not use unsuitable copper pipes or fittings.","Extinguishing: first, if it is safe to do so, close the gas valve. Do not extinguish a gas fire if you cannot stop the gas flow — the leaking gas can cause an explosion.","Civil Defense teams (115) use water spray from a distance to cool cylinders and tanks, not to extinguish the gas flame.","Gas detectors in gas storage areas: the alarm must sound well before the LEL is reached (typically at 10-20% of the LEL).","In factories: welding areas, forklift charging areas and battery rooms."]},{heading:"4. Class D — combustible metals (NFPA 484)",body:"Combustible metals — one of the most dangerous types:",points:["Fuels: magnesium, titanium, aluminum powder, sodium and lithium metal.","These metals burn at extremely high temperatures and give off very intense light; do not look directly at the flame.","Water is prohibited! Mg + H₂O → MgO + H₂ (hydrogen is produced and can explode).","CO₂ is prohibited! 2Mg + CO₂ → 2MgO + C (magnesium even burns in CO₂).","Class D extinguishers only, and only one whose label lists that metal: the agent differs from metal to metal (for example sodium chloride (NaCl)-based powder or graphite; copper powder for lithium). Never use water, ordinary powder or foam. Dry sand only if the site fire plan or the metal's SDS names it and it is completely dry.","Examples in factories: aluminum smelting, magnesium machining and lithium-metal batteries.","NFPA 484: storage, handling and protection of combustible metals (now part of NFPA 660).","Aluminum powder: also carries a risk of dust explosion (NFPA 654 / 660).","Response: call 115 immediately and use only a Class D extinguisher listed for that metal. Lithium-ion (Li-ion) batteries contain no metallic lithium and are cooled with water."]},{heading:"5. Combustible dust — dust explosions (NFPA 654)",body:"A deadly hazard in factories:",points:["The dust explosion pentagon: fuel (dust) + oxygen + heat (ignition) + dispersion in air + confinement.","Sources: flour, sugar, wood, coal, metal dust and plastics.","The minimum ignition temperature (MIT) varies with the type of dust; refer to the SDS or the dust test results.","The minimum explosible concentration (MEC) also varies with the type of dust; dust dispersed in the air is always dangerous.","Primary explosion: inside a piece of equipment (such as a filter or a mill).","Secondary explosion: the primary explosion lifts dust from floors, shelves and pipes, causing a larger and more deadly explosion.","Risk reduction: dust collection systems, explosion vents and suppression systems.","Housekeeping: a dust layer 0.8 mm (1/32 inch) thick over more than 5% of the floor area can create a hazard (NFPA 654 / OSHA).","Example: in 2008 at the Imperial Sugar refinery (USA), a sugar dust explosion killed 14 workers (CSB).","Standards: NFPA 654 (now NFPA 660) and OSHA 29 CFR 1910.272 (for grain handling facilities)."]},{heading:"6. Stages of fire development in a factory",body:"The 4 standard stages — in factories a fire can develop faster:",points:["Incipient: a small fire — a trained person may put it out with the right portable extinguisher, after the alarm is raised and 115 called, with the exit route behind them; if it does not go out at once, get out.","Growth: fire and smoke increase rapidly and sprinklers activate — get out and call 115.","Fully developed: after flashover — Civil Defense teams (115) only.","Decay: the fuel decreases, but the risk of backdraft and collapse remains.","In factories, high-rack storage, pallets and liquids can bring a fire to the fully developed stage faster than in homes.","Pressurized gas and liquid tanks heated by fire can explode as a BLEVE — evacuate the surrounding area quickly.","The factory plan must keep the access route for 115 teams and the fire hydrant locations ready and unobstructed.","Fire watch after hot work: during the work and for at least 1 hour after it is finished, then monitoring for up to 3 more hours as decided by the permit authorizing individual (NFPA 51B)."]},{heading:"7. Fire load and risk assessment",body:"Assessing the hazard in the factory:",points:["Fire load density (MJ/m²): the amount of energy that combustible materials can release per square meter. Average values from EN 1991-1-2 (Eurocode 1):","• Dwelling: about 780 MJ/m².","• Office: about 420 MJ/m².","• Library: about 1500 MJ/m².","• Warehouses and factories: calculated from the materials stored, and often higher than these values.","Risk assessment: risk = likelihood of occurrence × severity of the consequences.","• Low: controlled by normal procedures.","• Medium: requires additional controls and monitoring.","• High: requires urgent action before work continues.","• Extreme: work stops until the risk is reduced.","The fire resistance rating of walls and roofs is set by building codes according to the type and use of the building (such as NFPA 101 and NFPA 5000).","Update the facility risk assessment (such as an HVA) at least once a year and after every major change."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"Dust explosion",description:"A dust explosion demonstration"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"Fire class chart",description:"Fire classification in factories"}],quiz:[{question:"Which extinguisher is suitable for a Class D fire?",options:[{text:"ABC powder",correct:!1},{text:"Water",correct:!1},{text:"A Class D extinguisher listed for that metal",correct:!0},{text:"CO₂",correct:!1}],explanation:"Only a Class D extinguisher or agent whose label lists the burning metal is suitable; the agent differs from metal to metal. Do not use water, CO₂ or ABC powder."},{question:"What does BLEVE stand for?",options:[{text:"A fire alarm",correct:!1},{text:"Boiling Liquid Expanding Vapor Explosion",correct:!0},{text:"A sprinkler system",correct:!1},{text:"A class of gas",correct:!1}],explanation:"A BLEVE is the explosion of a pressurized liquid tank when it is heated by fire and the vapor expands rapidly."},{question:"How many elements does the dust explosion pentagon have?",options:[{text:"3",correct:!1},{text:"4",correct:!1},{text:"5",correct:!0},{text:"6",correct:!1}],explanation:"Five elements: fuel + oxygen + heat + dispersion + confinement."},{question:"What does acetylene form with copper?",options:[{text:"Nothing happens",correct:!1},{text:"Copper acetylide — an explosive compound",correct:!0},{text:"Cleaning",correct:!1},{text:"A small amount of heat",correct:!1}],explanation:"Acetylene forms a sensitive explosive compound with copper (copper acetylide) that detonates on impact or heating."},{question:"What hazard does aluminum powder present?",options:[{text:"Class A only",correct:!1},{text:"Class D and dust explosion",correct:!0},{text:"Gas only",correct:!1},{text:"No hazard",correct:!1}],explanation:"Aluminum powder is both a combustible metal (Class D) and a combustible dust (NFPA 484 / 654, now NFPA 660)."},{question:"According to EN 1991-1-2, what is the approximate average fire load in dwellings?",options:[{text:"100 MJ/m²",correct:!1},{text:"230 MJ/m²",correct:!1},{text:"420 MJ/m²",correct:!1},{text:"780 MJ/m²",correct:!0}],explanation:"The average fire load in dwellings is about 780 MJ/m², and in offices about 420 MJ/m² (EN 1991-1-2, Table E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"Fire suppression systems in factories",subtitle:"Portable extinguishers + fixed systems (sprinkler/foam/CO₂)",summary:"Portable extinguishers and fixed fire suppression systems in factories",blocks:[{body:"Factories need two levels of fire suppression: 1) portable extinguishers for small fires in their early stage, 2) fixed suppression systems for continuous protection. Depending on the type of hazard: sprinklers (NFPA 13), foam (NFPA 11 / 16), CO₂ (NFPA 12), dry chemical (NFPA 17) and clean agent (NFPA 2001). This module explains these systems and the inspection schedule."},{heading:"1. Portable extinguishers — selection for the factory",body:"The 7 main types and a selection guide:",points:["ABC powder (multipurpose): the most common type for corridors and general areas — A, B, C (not D or K).","CO₂: for electrical panels and server rooms — B, C.","Foam (AFFF): for flammable liquid storage and diked areas — A, B.","Wet chemical: for the factory kitchen and cafeteria — K.","Clean agent: for server and control rooms.","Class D (agent listed on the label for the metal in use): for metal machining and aluminum smelting.","Water mist (fine deionized water): for A, and some models for C — according to the device listing.","Hazard levels under NFPA 10 (minimum Class A extinguisher rating):","• Light hazard (offices): 2-A.","• Ordinary hazard (typical factory): 2-A.","• Extra hazard (factory with large amounts of combustibles): 4-A.","Travel distance to an extinguisher:","• Class A: up to 23 meters (75 feet) at all hazard levels.","• Class B: 9 or 15 meters (30 / 50 feet) depending on the extinguisher rating and the hazard level."]},{heading:"2. Sprinkler systems — NFPA 13",body:"The most important fixed system in many factories:",points:["The 4 types of sprinkler system:","• Wet pipe: the pipes are always full of water — the fastest response and the most common type.","• Dry pipe: the pipes are filled with pressurized air or nitrogen — for areas where the temperature drops below 4°C.","• Pre-action: the valve opens only after detectors sense a fire, then the sprinkler head opens from the heat — for areas with sensitive equipment.","• Deluge: open heads that all discharge water at once — for high-hazard areas.","Activation temperature and glass bulb color:","• 57°C (orange): ordinary temperature rating — areas with low ambient temperatures.","• 68°C (red): ordinary temperature rating — the most common in offices and factories.","• 79°C (yellow) and 93°C (green): intermediate temperature rating — warmer areas.","• 141°C (blue): high temperature rating — boiler rooms and near hot equipment.","Coverage area per standard spray head: up to about 21 m² (light hazard), 12 m² (ordinary hazard) and 9 m² (extra hazard).","Water density: 0.10-0.40 gpm/ft² (about 4-16 mm/min) depending on the hazard level.","NFPA 25: inspection and testing on weekly, monthly, annual and 5-year schedules.","Sprinklers open only where the fire is; the heads do not all open at once (except in a deluge system)."]},{heading:"3. Foam systems — NFPA 11 / 16",body:"For large flammable liquid storage facilities:",points:["The 3 types of foam by expansion ratio:","• Low expansion (up to 20:1): tank fires and liquid spills.","• Medium expansion (20:1 to 200:1): diked areas.","• High expansion (200:1 to 1000:1): aircraft hangars and large enclosed spaces.","Types of foam concentrate:","• AFFF: for hydrocarbons (gasoline, diesel).","• AR-AFFF (Alcohol-Resistant): for polar solvents (alcohol, acetone).","• Fluoroprotein: for storage tanks.","• Fluorine-free foam (F3): the replacement for PFAS foams.","Application rate:","• Hydrocarbon spills: a minimum of about 4.1 L/min/m² (0.10 gpm/ft²).","• Polar solvents: according to the manufacturer's listing, generally higher.","PFAS hazard: AFFF contains fluorinated substances (PFAS) that accumulate in the body and the environment; many countries are moving to fluorine-free foam (F3).","In industry: tank farms, tanker loading racks and refineries."]},{heading:"4. CO₂ and clean agent systems — NFPA 12 / 2001",body:"For equipment rooms and total flooding:",points:["Total flooding with CO₂:","• Design concentration: a minimum of 34% (NFPA 12), and higher for some materials.","• Hazard: the extinguishing concentration is lethal to people — no one may remain in the room.","• Pre-discharge alarm and time delay: must be long enough to evacuate the room before the gas is released (NFPA 12).","• Applications: generator rooms, engine test cells and printing presses.","Clean agent (FK-5-1-12 / HFC-227ea):","• NOAEL: in occupied spaces, the design concentration does not exceed the no-observed-adverse-effect level (NOAEL) (NFPA 2001); even so, evacuate the room.","• Design concentration: generally about 4-9% depending on the agent.","• Discharge: halocarbon agents within 10 seconds (NFPA 2001).","• Applications: server rooms, control rooms and switchgear rooms.","• It costs much more than water-based systems.","Halon 1301: under the Montreal Protocol, its production has been halted in developed countries since 1994 because it depletes the ozone layer; new systems are not installed with it.","Hydrostatic testing of portable extinguishers (NFPA 10): CO₂ every 5 years, clean agent every 12 years; fixed-system cylinders according to NFPA 12 / 2001 and cylinder regulations."]},{heading:"5. Dry chemical systems — NFPA 17",body:"For special hazards:",points:["Pre-engineered systems:","• Commercial kitchens: wet chemical systems (NFPA 17A) are now generally used, not dry chemical.","• Paint spray booths.","• Protection of heavy equipment and vehicles.","• Dip tanks.","Agents:","• Sodium bicarbonate: B, C.","• Potassium bicarbonate (Purple-K): B, C — more effective than sodium bicarbonate on Class B fires.","• Monoammonium phosphate: A, B, C.","• Potassium chloride: B, C.","Activation: a heat detector or a manual pull station.","After discharge: the powder spreads everywhere and can damage electronic equipment; cleanup is difficult.","The coverage area of each nozzle is set by the system listing."]},{heading:"6. Fire detection — NFPA 72",body:"The detection system — the first line of warning:",points:["Types of detectors:","• Smoke: photoelectric for smoldering fires, ionization for flaming fires.","• Heat: fixed temperature (for example 57°C) or rate-of-rise.","• Flame: UV/IR detectors, which detect flames quickly.","• Gas: LEL detectors and CO sensors.","• Air sampling: for server rooms — the most sensitive type.","Spacing and coverage:","• Smoke: spacing between detectors of about 9 meters (30 ft) on a smooth ceiling (NFPA 72).","• Heat: according to the detector's listed spacing.","• Flame: according to the device's field of view and listed distance.","Alarm notification:","• Audible: generally at least 15 dB above the average ambient sound level (NFPA 72).","• Visual (strobe): for noisy areas and for people with hearing impairments.","• Voice / mass notification: for large buildings and facilities.","Inspection and testing: according to the NFPA 72 schedules (many devices are tested once a year)."]},{heading:"7. Inspection and maintenance schedule",body:"According to NFPA standards:",points:["Daily / weekly:","• Visual inspection (gauge pressure, damage).","• Check that nothing is obstructing the sprinklers.","• Running the fire pump without water flow (no-flow test): diesel pumps every week, electric pumps generally every month (NFPA 25).","Monthly:","• Visual inspection of portable extinguishers (NFPA 10).","• Inspection of the fire alarm panel and trouble signals.","• Inspection of manual pull stations — visible and unobstructed.","Annually:","• Annual maintenance of portable extinguishers by a qualified person (not hydrostatic testing).","• Inspection of sprinklers from floor level (NFPA 25).","• A sample of foam concentrate sent for testing.","• Testing of detectors and alarms (NFPA 72).","Every few years:","• Hydrostatic test of extinguishers (pressure test of the cylinder, NFPA 10): every 5 years for water, foam, wet chemical, CO₂ and stainless-steel dry chemical units; every 12 years for stored-pressure dry chemical units with mild steel, brazed brass or aluminum shells, and for clean agent units. Separately, every 6 years, stored-pressure dry chemical extinguishers that need the 12-year test are emptied and checked inside by a qualified person. The rules for Duhok are not yet confirmed.","• Internal inspection of sprinkler piping: every 5 years (NFPA 25).","• Replacement or sample testing of sprinkler heads after 50 years (standard heads — NFPA 25).","Recordkeeping: document every inspection and test, and keep the records as required by the standards and the relevant authorities."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"Sprinkler activation",description:"A sprinkler demonstration"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"Suppression systems chart",description:"Fixed systems"}],quiz:[{question:"For most factories, which is the most important fixed system?",options:[{text:"Portable extinguishers",correct:!1},{text:"Sprinklers (NFPA 13)",correct:!0},{text:"CO₂ only",correct:!1},{text:"None of these",correct:!1,fixed:!0}],explanation:"Sprinklers operate automatically and control a fire in its early stage, even when no one is on site; portable extinguishers are only for small fires."},{question:"Where is a wet pipe system not suitable?",options:[{text:"Equipment rooms (ICT)",correct:!1},{text:"Offices",correct:!1},{text:"Areas where the temperature drops below 4°C",correct:!0},{text:"Warehouses",correct:!1}],explanation:"In cold areas the water in the pipes freezes; a dry pipe system is suitable."},{question:"Are new systems installed with Halon 1301?",options:[{text:"Yes",correct:!1},{text:"No — its production has been halted under the Montreal Protocol",correct:!0},{text:"Only in ICT rooms",correct:!1},{text:"Only in server rooms",correct:!1}],explanation:"Halon 1301 depletes the ozone layer; its production in developed countries has been halted since 1994."},{question:"Why must everyone leave the room before a total flooding CO₂ system discharges?",options:[{text:"It is not necessary; CO₂ is harmless",correct:!1},{text:"Because the extinguishing concentration (34% and above) is lethal to people",correct:!0},{text:"Because CO₂ sprays water",correct:!1},{text:"Because CO₂ makes a loud noise",correct:!1}],explanation:"The CO₂ design concentration in total flooding systems is at least 34% (NFPA 12), and this concentration causes unconsciousness and death within a short time; that is why there is a pre-discharge alarm and a time delay."},{question:"What is the approximate coverage area per standard spray sprinkler head?",options:[{text:"2-5 m²",correct:!1},{text:"12-21 m²",correct:!0},{text:"50 m²",correct:!1},{text:"100 m²",correct:!1}],explanation:"According to NFPA 13: about 21 m² for light hazard and 12 m² for ordinary hazard; for extra hazard it is smaller (about 9 m²)."},{question:"What does the weekly test of a diesel fire pump involve?",options:[{text:"A visual inspection only",correct:!1},{text:"Starting the pump without water flow (no-flow test)",correct:!0},{text:"A hydrostatic test",correct:!1},{text:"None of these",correct:!1,fixed:!0}],explanation:"NFPA 25: the diesel pump is started and tested without water flow every week, and the electric pump generally every month."}]}],t={lessons:e};export{t as default,e as lessons};
